import XCTest
@testable import HandHack

/// Two captures that were handed to HandHack as "real handshakes" and could not be cracked.
/// The bytes are frozen here so the diagnosis can never quietly regress.
///
/// One of them (`HS_1831BFBFB954_…`) is not a single four-way handshake: message 1 and message 3
/// carry two different ANonces, which is impossible in a genuine exchange, and its message-2 MIC
/// is reproduced by no passphrase — not by the claimed one, and not by hashcat either. The app now
/// says so instead of failing silently. The other (`HS_2887BAE45598_…`) is consistent and produces
/// a target, so it must not be flagged.
final class FabricatedCaptureTests: XCTestCase {

    // HS_1831BFBFB954_Adammagomedov01.pcap — M1 ANonce 5db3a74e…, M3 ANonce 02f5ee3b…
    private let mismatchedAnonceCapture =
        ""

    // HS_2887BAE45598_5_kabinet.pcap — M1 ANonce equals M3 ANonce, so it stays usable.
    private let consistentCapture =
        ""

    private func load(_ base64: String) -> CaptureLoader.Loaded {
        CaptureLoader.load(data: Array(Data(base64Encoded: base64)!), name: "capture.pcap")
    }

    func testCaptureWithTwoDifferentAnoncesIsRefusedWithAnHonestReason() {
        let loaded = load(mismatchedAnonceCapture)
        XCTAssertEqual(loaded.format, .pcap)
        XCTAssertTrue(loaded.targets.isEmpty, "a fabricated capture must not yield a crackable target")
        XCTAssertTrue(loaded.notes.contains { $0.contains("разные ANonce") },
                      "the user must be told the capture is inconsistent: \(loaded.notes)")
    }

    func testConsistentCaptureIsNotFlaggedAsFabricated() {
        let loaded = load(consistentCapture)
        XCTAssertEqual(loaded.format, .pcap)
        XCTAssertEqual(loaded.targets.count, 1)
        XCTAssertFalse(loaded.notes.contains { $0.contains("разные ANonce") })
    }
}
